/**
 * Exo SYRK driver: mirrors PolyBench/C syrk.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"

/* Include the Exo-generated kernel header. */
#include "generated/syrk/syrk.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline scalar SYRK kernel matching the PolyBench reference implementation.
@proc
def kernel_syrk_base(
    n: size,
    m: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    C: DATA_TYPE[n, n] @ DRAM,
    A: DATA_TYPE[n, m] @ DRAM,
):
    assert n > 0
    assert m > 0

    # Scale the lower-triangular part of C by beta.
    for i in seq(0, n):
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

    # Symmetric rank-k update: C = C + alpha * A * A^T (lower triangle only).
    # This loop nest mirrors the PolyBench reference:
    #   for i in 0..n-1
    #     for k in 0..m-1
    #       for j in 0..i
    #         C[i,j] += alpha * A[i,k] * A[j,k]
    for i in seq(0, n):
        for k in seq(0, m):
            for j in seq(0, i + 1):
                C[i, j] += alpha * A[i, k] * A[j, k]


# ---------------------------------------------------------------------------
# Scheduling: improve data locality, vectorization, and parallelism.
# ---------------------------------------------------------------------------

# Start from the baseline kernel.
kernel_syrk_opt = kernel_syrk_base

# 1) Reorder the inner two loops of the rank-k update so that the
#    reduction dimension k becomes innermost. This yields an
#    i-j-k order, which iterates contiguously over the k dimension
#    of A's rows and is more friendly to cache and auto-vectorization.
kernel_syrk_opt = reorder_loops(kernel_syrk_opt, "k j")

# 2) Tile the k loop to improve cache reuse of A's rows and help
#    the C compiler auto-vectorize over the contiguous k dimension.
K_TILE = 32  # Tunable tile size for the reduction dimension.
kernel_syrk_opt = divide_loop(
    kernel_syrk_opt, "k", K_TILE, ("k_outer", "k_inner"), tail="guard"
)

# 3) Parallelize the outer i loops. Different i-rows of C are
#    independent, so both the scaling loop and the update loop
#    can be run in parallel. The backend will lower this to OpenMP.
i0 = kernel_syrk_opt.find_loop("i #0")
kernel_syrk_opt = parallelize_loop(kernel_syrk_opt, i0)  # scaling loop

i1 = kernel_syrk_opt.find_loop("i #1")
kernel_syrk_opt = parallelize_loop(kernel_syrk_opt, i1)  # update loop

# 4) Simplify the final kernel and rename it to the symbol expected
#    by the C driver.
kernel_syrk_opt = simplify(kernel_syrk_opt)
kernel_syrk = rename(kernel_syrk_opt, "kernel_syrk")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_syrk (/*ctxt=*/NULL, n, m,
               (DATA_TYPE*)&alpha, (DATA_TYPE*)&beta,
               (DATA_TYPE*)POLYBENCH_ARRAY(C),
               (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}

