    # Problem sizes must be positive.
    assert n > 0
    assert m > 0

    for i in seq(0, n):
        # Scale the lower triangular part of row i of C by beta.
        for j in seq(0, i + 1):
            C[i, j] = beta * C[i, j]

        # Rank-k update: accumulate alpha * A[i, k] * A[j, k] into C[i, j].
        # We precompute alpha * A[i, k] once per (i, k) and reuse it across j.
        for k in seq(0, m):
