# Tile the k (reduction) loop to keep working sets of A in cache.
TK = 64
s = divide_loop(s, s.find_loop("k"), TK, ["ko", "ki"], tail="guard")

# Parallelize the outermost tiled i-loop across cores (emits OpenMP pragmas).
s = parallelize_loop(s, s.find_loop("io"))

